sys_script_include.script:
// Script Include: AgendamentoRepository
// Camada: INFRAESTRUTURA — acesso a dados de x_espaco_agendamento via GlideRecord.
var AgendamentoRepository = Class.create();
AgendamentoRepository.prototype = {
    initialize: function() {
        this.TABLE = 'x_espaco_agendamento';
    },

    findById: function(sysId) {
        var gr = new GlideRecord(this.TABLE);
        return gr.get(sysId) ? gr : null;
    },

    type: 'AgendamentoRepository'
};
